            //
            aOrbiterC = (aOrbiterC + aOrbiterE) + 0xA5D3E9EB3139F052ULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterC) ^ 0xDE9F38A933A2AF1DULL) ^ aOUSaltD[(((511U - aIndex) + 423U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x384B917F0EF63627ULL), 43U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterH) + 0xA29D4378336C2262ULL;
