            aScatter = (RotL64(aPrevious, 56U) ^ RotL64(aCross, 27U)) + (RotL64(aCarry, 11U) ^ RotL64(aIngress, 41U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterB = ((aWandererD + RotL64(aPrevious, 48U)) + 0xED4F2B23EA5D6DD5ULL) + aOASaltA[((aIndex + 280U)) & S_SALT1];
            aOrbiterK = (aWandererK + RotL64(aIngress, 53U)) + 0x9ACC41CAFE65E215ULL;
            aOrbiterD = (aWandererH + RotL64(aScatter, 27U)) + 0x1EEE288BF39580AFULL;
            aOrbiterE = ((aWandererC + RotL64(aCross, 13U)) + RotL64(aCarry, 29U)) + 0x8784AEA9C5F22079ULL;
            aOrbiterG = ((aWandererF + RotL64(aIngress, 43U)) + RotL64(aCarry, 19U)) + 0x2BC3F74DB17AE291ULL;
