            aWandererJ = aWandererJ + ((((RotL64(aIngress, 47U) + RotL64(aOrbiterJ, 27U)) + aOrbiterB) + RotL64(aCarry, 29U)) + aWUSaltH[(((511U - aIndex) + 46U)) & S_SALT1]);
