            aOrbiterF = ((aOrbiterF + aOrbiterD) + 0x739887A0DB47B461ULL) + aOUSaltC[(((511U - aIndex) + 49U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterF) ^ 0x5CED679B58470AE6ULL;
