            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererH = aWandererH + (((RotL64(aIngress, 37U) + RotL64(aOrbiterI, 47U)) + aOrbiterK) + RotL64(aCarry, 11U));
            aWandererK = aWandererK ^ (((RotL64(aCross, 39U) + aOrbiterG) + RotL64(aOrbiterH, 57U)) + aWUSaltG[((aIndex + 284U)) & S_SALT1]);
