            aWandererG = aWandererG ^ ((RotL64(aPrevious, 35U) + aOrbiterE) + RotL64(aOrbiterA, 35U));
            aWandererB = aWandererB + (((RotL64(aScatter, 30U) + aOrbiterD) + RotL64(aOrbiterG, 3U)) + RotL64(aCarry, 53U));
            aWandererF = aWandererF ^ ((RotL64(aIngress, 13U) + RotL64(aOrbiterD, 29U)) + aOrbiterI);
            aWandererJ = aWandererJ + ((RotL64(aCross, 23U) + RotL64(aOrbiterF, 54U)) + aOrbiterJ);
            aWandererD = aWandererD ^ ((RotL64(aPrevious, 47U) + RotL64(aOrbiterC, 41U)) + aOrbiterB);
            aWandererA = aWandererA + (((RotL64(aIngress, 3U) + RotL64(aOrbiterB, 37U)) + aOrbiterH) + aWUSaltH[(((511U - aIndex) + 223U)) & S_SALT1]);
            //
            aCarry = aCarry + (RotL64(aWandererH, 60U) ^ aWandererF);
            aCarry = aCarry + (RotL64(aWandererB, 21U) ^ aWandererG);
            aCarry = aCarry + (aWandererE ^ RotL64(aWandererK, 3U));
