            aOrbiterA = (aWandererC + RotL64(aScatter, 43U)) + 0x668770D4BC1166EAULL;
            aOrbiterE = (aWandererF + RotL64(aPrevious, 53U)) + 0x15A6E87A5DA41A5EULL;
            aOrbiterG = (((aWandererH + RotL64(aCross, 3U)) + RotL64(aCarry, 3U)) + 0x1038476FB9BC82CEULL) + aOASaltB[((aIndex + 281U)) & S_SALT1];
            aOrbiterI = (aWandererG + RotL64(aPrevious, 13U)) + 0x421BAB689BE5EE3EULL;
            aOrbiterJ = ((aWandererI + RotL64(aCross, 21U)) + 0xC11E6D6EAE8F6BF5ULL) + aOASaltF[((aIndex + 105U)) & S_SALT1];
