            aScatter = TwistMix64::DiffuseB((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterB = (((aWandererF + RotL64(aCross, 53U)) + RotL64(aCarry, 27U)) + 0xE36832C8D731D055ULL) + aOASaltD[(((511U - aIndex) + 27U)) & S_SALT1];
            aOrbiterE = (aWandererJ + RotL64(aIngress, 23U)) + 0x2D0FC6C2F959B1B4ULL;
            aOrbiterD = ((aWandererH + RotL64(aScatter, 13U)) + 0x8A26BA8AA76ED97EULL) + aOASaltG[(((511U - aIndex) + 195U)) & S_SALT1];
            aOrbiterJ = ((aWandererB + RotL64(aPrevious, 38U)) + 0x821283AA467BB01CULL) + aOASaltH[((aIndex + 415U)) & S_SALT1];
            aOrbiterK = (aWandererA + RotL64(aIngress, 29U)) + 0x384EC2A63F365705ULL;
            aOrbiterH = (((aWandererI + RotL64(aPrevious, 3U)) + RotL64(aCarry, 3U)) + 0xA521B761F15ADD84ULL) + aOASaltC[(((511U - aIndex) + 332U)) & S_SALT1];
            aOrbiterA = ((aWandererK + RotL64(aScatter, 47U)) + RotL64(aCarry, 41U)) + 0xACC2E372980AB3C8ULL;
