            aOrbiterD = RotL64((aOrbiterD * 0x764690AA6CD52BF7ULL), 3U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterJ) + 0x7621B0199E7CAE0CULL) + aOUSaltC[((aIndex + 479U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterE) ^ 0x56BB7E2D9F60B2CCULL;
            aOrbiterK = RotL64((aOrbiterK * 0x4AA82CF5D861303FULL), 13U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterH) + 0xAE1FDF1E420C0DDCULL) + aOUSaltF[(((511U - aIndex) + 122U)) & S_SALT1];
