            //
            aOrbiterD = (aOrbiterD + aOrbiterK) + 0xE2398A7CF8C6B918ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterD) ^ 0x36854D17655DBF14ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x6060D8A41F8A968BULL), 29U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterB) + 0x7BD31B41A48084BFULL) + aOUSaltB[(((511U - aIndex) + 203U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterA) ^ 0x8E2E506B1C7E4189ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x714EC70D06075519ULL), 51U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterD) + 0xDFC75C293ED52312ULL) + aOUSaltE[((aIndex + 61U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterJ) ^ 0x0698464A5A6ACF2EULL;
            aOrbiterH = RotL64((aOrbiterH * 0x2BD232B17872A35BULL), 35U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterA) + 0x7ACA493DE7F6774DULL) + aOUSaltG[(((511U - aIndex) + 259U)) & S_SALT1];
