            aWandererH = aWandererH ^ ((RotL64(aIngress, 5U) + RotL64(aOrbiterH, 10U)) + aOrbiterK);
            aWandererK = aWandererK + ((RotL64(aCross, 47U) + aOrbiterJ) + RotL64(aOrbiterA, 43U));
