            aOrbiterA = ((aOrbiterA + aOrbiterF) + 0x6F8BFAB28FBC6BB5ULL) + aOUSaltA[((aIndex + 111U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterA) ^ 0x3B50DA2BB0496BF1ULL;
